import{_ as t,o as r,c as a,ag as i}from"./chunks/framework.Ccn6roXv.js";const u=JSON.parse('{"title":"8. Security properties","description":"The core properties to preserve when building or testing server functions.","frontmatter":{"title":"8. Security properties","description":"The core properties to preserve when building or testing server functions."},"headers":[],"relativePath":"guide/08-security-properties.md","filePath":"guide/08-security-properties.md"}'),o={name:"guide/08-security-properties.md"};function s(l,e,n,p,c,d){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="security-properties" tabindex="-1">Security properties <a class="header-anchor" href="#security-properties" aria-label="Permalink to &quot;Security properties&quot;">​</a></h1><p>Security properties are the facts that must remain true even when a request is modified.</p><p>Use these properties as a checklist while reading code or testing traffic.</p><h2 id="boundary-clarity" tabindex="-1">Boundary clarity <a class="header-anchor" href="#boundary-clarity" aria-label="Permalink to &quot;Boundary clarity&quot;">​</a></h2><p>The application must know which values are client-controlled.</p><p>If a value crosses from browser to server, it is input.</p><h2 id="runtime-validation" tabindex="-1">Runtime validation <a class="header-anchor" href="#runtime-validation" aria-label="Permalink to &quot;Runtime validation&quot;">​</a></h2><p>The server must check actual request values at runtime.</p><p>TypeScript helps developers write code. It does not validate HTTP traffic.</p><h2 id="least-authority" tabindex="-1">Least authority <a class="header-anchor" href="#least-authority" aria-label="Permalink to &quot;Least authority&quot;">​</a></h2><p>The handler should use only the authority needed for the requested action.</p><p>Role, tenant, and account decisions should come from trusted server state.</p><h2 id="allow-listed-state-changes" tabindex="-1">Allow-listed state changes <a class="header-anchor" href="#allow-listed-state-changes" aria-label="Permalink to &quot;Allow-listed state changes&quot;">​</a></h2><p>State changes should write known fields.</p><p>Avoid patterns that copy all request keys into persistent objects.</p><h2 id="safe-error-behavior" tabindex="-1">Safe error behavior <a class="header-anchor" href="#safe-error-behavior" aria-label="Permalink to &quot;Safe error behavior&quot;">​</a></h2><p>Errors should help the legitimate caller without exposing internals.</p><p>Detailed stack traces, internal markers, and framework paths are useful during development. They should not be returned to untrusted clients in production.</p><h2 id="observable-rejection" tabindex="-1">Observable rejection <a class="header-anchor" href="#observable-rejection" aria-label="Permalink to &quot;Observable rejection&quot;">​</a></h2><p>A rejected request should fail cleanly.</p><p>Good outcomes include:</p><ul><li>No state change</li><li>Generic error text</li><li>Stable status code</li><li>No stack trace</li><li>No platform error page</li></ul><h2 id="security-property" tabindex="-1">Security property <a class="header-anchor" href="#security-property" aria-label="Permalink to &quot;Security property&quot;">​</a></h2><p>The property to preserve is predictable enforcement:</p><ul><li>Invalid wire data stops at decoding.</li><li>Invalid application data stops at validation.</li><li>Unauthorized actions stop before state changes.</li><li>Errors do not disclose internal implementation details.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Next, look at common failure patterns that break these properties.</p>',27)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
